function beta_cm_fail(string $msg, int $code = 400): never {
    while (ob_get_level() > 0) { ob_end_clean(); }
    http_response_code($code); header('Content-Type: application/json');
    echo json_encode(['success' => false, 'error' => $msg]); exit();
}
function beta_cm_out(array $body): never {
    while (ob_get_level() > 0) { ob_end_clean(); }
    header('Content-Type: application/json'); header('Cache-Control: no-store');
    echo json_encode($body); exit();
}
if ($_SERVER['REQUEST_METHOD'] !== 'GET') beta_cm_fail('Unknown action.');
// API endpoint to fetch subscribers
$subscribersURL = "https://api.twitch.tv/helix/subscriptions?broadcaster_id=$broadcasterID";

$allSubscribers = [];
$subscribersForCurrentPage = [];
$displaySearchBar = false;
$totalPages = 0;
$currentPage = 1;
$subscribersError = null;
$showNoSubscriberAccessMessage = false;
$channelDisplayName = t('subscribers_default_channel_name');

// Determine broadcaster type first, so non-affiliate/partner channels show a friendly message.
$usersUrl = "https://api.twitch.tv/helix/users?id=$broadcasterID";
$curl = curl_init($usersUrl);
curl_setopt($curl, CURLOPT_HTTPHEADER, [
    'Authorization: Bearer ' . $authToken,
    'Client-ID: ' . $clientID
]);
curl_setopt($curl, CURLOPT_RETURNTRANSFER, true);
$usersResponse = curl_exec($curl);

if ($usersResponse === false) {
    $subscribersError = t('subscribers_error_eligibility');
} else {
    $usersHttpCode = curl_getinfo($curl, CURLINFO_HTTP_CODE);
    if ($usersHttpCode === 401) beta_twitch_401();
    if ($usersHttpCode !== 200) {
        $subscribersError = t('subscribers_error_eligibility');
    } else {
        $usersData = json_decode($usersResponse, true);
